from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel
import uvicorn
from jade.orchestrator import run_jade

class ChatRequest(BaseModel):
    query: str
    profile: str | None = "depth"
    num_results: int | None = 50
    subpages: int | None = 5
    livecrawl: str | None = "preferred"

app = FastAPI()
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])

@app.post("/api/jade")
async def api_jade(req: ChatRequest):
    return await run_jade(q=req.query, profile=req.profile, num_results=req.num_results, subpages=req.subpages, livecrawl=req.livecrawl)

@app.get("/healthz")
def health():
    return {"ok": True}

app.mount("/", StaticFiles(directory="frontend", html=True), name="frontend")

if __name__ == "__main__":
    uvicorn.run("main:app", host="0.0.0.0", port=8000, reload=False)
