import os, asyncio, json
import requests
from exa_py import Exa

EXA_API_KEY = os.environ["EXA_API_KEY"]
XAI_API_KEY = os.environ["XAI_API_KEY"]
CEREBRAS_API_KEY = os.environ["CEREBRAS_API_KEY"]

def exa_collect(query, num_results, subpages, livecrawl):
    exa = Exa(EXA_API_KEY)
    res = exa.search_and_contents(query=query, text=True, highlights=True, livecrawl=livecrawl, num_results=num_results, subpages=subpages)
    items = []
    for r in res.results:
        t = getattr(r, "text", None)
        if t:
            items.append({"url": r.url, "title": getattr(r, "title", "") or "", "text": t})
    return items

def build_evidence(items, max_chars=120000):
    parts = []
    used = 0
    cites = []
    for it in items:
        txt = it["text"]
        if not txt:
            continue
        remaining = max_chars - used
        if remaining <= 0:
            break
        chunk = txt[:remaining]
        parts.append(chunk)
        used += len(chunk)
        cites.append({"url": it["url"], "title": it["title"]})
    return "\n\n".join(parts), cites

def call_cerebras(messages, model="gpt-oss-120b", response_format=None, max_tokens=1400):
    headers = {"Authorization": f"Bearer {CEREBRAS_API_KEY}", "Content-Type": "application/json"}
    payload = {"model": model, "messages": messages, "stream": False, "max_tokens": max_tokens}
    if response_format:
        payload["response_format"] = response_format
    r = requests.post("", headers=headers, json=payload, timeout=180)
    r.raise_for_status()
    return r.json()["choices"][0]["message"]["content"]

def call_grok(messages, model="grok-4", response_format=None, max_tokens=1400):
    headers = {"Authorization": f"Bearer {XAI_API_KEY}", "Content-Type": "application/json"}
    payload = {"model": model, "messages": messages, "stream": False, "max_tokens": max_tokens}
    if response_format:
        payload["response_format"] = response_format
    r = requests.post("", headers=headers, json=payload, timeout=180)
    r.raise_for_status()
    return r.json()["choices"][0]["message"]["content"]

async def run_jade(q, profile="depth", num_results=50, subpages=5, livecrawl="preferred"):
    loop = asyncio.get_event_loop()
    items = await loop.run_in_executor(None, exa_collect, q, num_results, subpages, livecrawl)
    evidence, citations = build_evidence(items)
    if profile == "speed":
        out = call_grok(
            [
                {"role": "system", "content": "Jade egy kritikus kutató, aki források alapján válaszol, strukturált JSON kimenettel."},
                {"role": "user", "content": f"Kérdés: {q}\n\nBizonyíték:\n{evidence}\n\nAdj JSON-t a mezőkkel: answer,key_points,citations,doubts,followups."}
            ],
            model="grok-4-fast",
            response_format={"type": "json_object"}
        )
    elif profile == "code":
        out = call_cerebras(
            [
                {"role": "system", "content": "Jade rigorózus kódasszisztens, aki pontos megoldást ad."},
                {"role": "user", "content": f"{q}\n\nKörnyezet:\n{evidence}\n\nAdj JSON-t a mezőkkel: answer,key_points,citations,doubts,followups."}
            ],
            model="qwen-3-coder-480b",
            response_format={"type": "json_object"}
        )
    else:
        draft = call_cerebras(
            [
                {"role": "system", "content": "Jade gondos kutató, aki hivatkozásokkal dolgozik és strukturált JSON-t ad vissza."},
                {"role": "user", "content": f"Válaszolj a bizonyíték alapján.\nKérdés: {q}\n\nBizonyíték:\n{evidence}\n\nAdj JSON-t a mezőkkel: answer,key_points,citations,doubts,followups."}
            ],
            model="gpt-oss-120b",
            response_format={"type": "json_object"}
        )
        out = call_grok(
            [
                {"role": "system", "content": "Javítsd és ellenőrizd a JSON választ, tartsd a sémát változatlanul."},
                {"role": "user", "content": draft}
            ],
            model="grok-4",
            response_format={"type": "json_object"}
        )
    data = json.loads(out)
    data["citations"] = citations
    return {"model": "Jade", "output": data}
```

