async function postJSON(url, data) {
  const r = await fetch(url, {method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify(data)});
  if (!r.ok) throw new Error(await r.text());
  return r.json();
}
function el(id){return document.getElementById(id)}
function setStatus(t){el("status").textContent=t}
function renderAnswer(o){
  const a = el("answer")
  a.innerHTML = "<h2>Válasz</h2><div>"+(o.answer||"")+"</div>"
  const k = el("keys")
  k.innerHTML = "<h2>Kulcspontok</h2>" + (Array.isArray(o.key_points)?o.key_points.map(x=>"<div class='key'>"+x+"</div>").join(""):"")
  const c = el("cites")
  c.innerHTML = "<h2>Források</h2>" + (Array.isArray(o.citations)?o.citations.map(x=>"<div class='cite'>"+(x.title||x.url)+"</div>").join(""):"")
  const d = el("doubts")
  d.innerHTML = "<h2>Kétségek</h2><div>"+(Array.isArray(o.doubts)?o.doubts.join("<br>"):"")+"</div>"
  const f = el("follows")
  f.innerHTML = "<h2>Következő lépések</h2><div>"+(Array.isArray(o.followups)?o.followups.join("<br>"):"")+"</div>"
}
async function onSubmit(e){
  e.preventDefault()
  const q = el("q").value.trim()
  const profile = el("profile").value
  if(!q) return
  setStatus("Fut...")
  el("answer").innerHTML=""
  el("keys").innerHTML=""
  el("cites").innerHTML=""
  el("doubts").innerHTML=""
  el("follows").innerHTML=""
  try{
    const res = await postJSON("/api/jade", {query:q, profile})
    setStatus("Kész")
    renderAnswer(res.output)
  }catch(err){
    setStatus("Hiba: "+err.message)
  }
}
document.getElementById("chat-form").addEventListener("submit", onSubmit)
if("serviceWorker" in navigator){navigator.serviceWorker.register("/service-worker.js")}
